-- Phase 8.2C production prerequisite guard. Metadata checks only; no table/data writes.
-- This expects the reviewed PRE-INSTALL schema, not an already-migrated staging database.
-- Extra organization/membership/subscription/branding/settings objects are untouched.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
SET LOCAL lock_timeout = '5s';
DO $phase82c$
DECLARE
  v_tables text[] := ARRAY['check_in_logs','groups','guests','service_days','shift_notes','staff_profiles','venues'];
  actual jsonb;
  row_item record;
  role_name text;
BEGIN
  IF current_setting('server_version_num')::integer < 170000 THEN
    RAISE EXCEPTION 'Phase 8.2C requires reviewed PostgreSQL 17+ privilege semantics';
  END IF;
  IF to_regclass('auth.users') IS NULL OR to_regprocedure('auth.uid()') IS NULL THEN
    RAISE EXCEPTION 'Auth prerequisites missing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='auth' AND table_name='users' AND column_name='id' AND udt_name='uuid')
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='auth' AND table_name='users' AND column_name='email' AND udt_name IN ('varchar','text')) THEN
    RAISE EXCEPTION 'Auth identity column compatibility changed';
  END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(v_tables) AND c.relkind='r' AND c.relrowsecurity AND NOT c.relforcerowsecurity AND pg_get_userbyid(c.relowner)='postgres') <> 7 THEN
    RAISE EXCEPTION 'Expected seven postgres-owned operational RLS tables';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='doorflow_invitation_private')
     OR EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('staff_invitations','staff_invitation_attempts','staff_invitation_audit'))
     OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'doorflow%staff_invitation%') THEN
    RAISE EXCEPTION 'Invitation object collision: stop and review; never overwrite';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('check_in_logs_group_id_idx','check_in_logs_guest_id_idx','groups_service_day_id_idx','guests_added_by_user_id_idx','guests_group_id_idx','shift_notes_created_by_user_id_idx','staff_invitation_attempts_venue_id_idx')) THEN
    RAISE EXCEPTION 'Advisor index name collision: stop and review';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname IN ('anon','authenticated') AND (rolsuper OR rolbypassrls))
     OR (SELECT count(*) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) <> 3
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role' AND rolbypassrls AND NOT rolsuper) THEN
    RAISE EXCEPTION 'Browser role prerequisites changed';
  END IF;

  -- Reviewed columns; exact comparison prevents silent schema drift.
  SELECT coalesce(jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default,'position',ordinal_position) ORDER BY table_name,ordinal_position),'[]'::jsonb) INTO actual FROM information_schema.columns WHERE table_schema='public' AND table_name=ANY(v_tables);
  IF actual IS DISTINCT FROM $expected$[{"column":"id","default":"gen_random_uuid()","nullable":"NO","position":1,"table":"check_in_logs","type":"uuid"},{"column":"guest_id","default":null,"nullable":"YES","position":2,"table":"check_in_logs","type":"uuid"},{"column":"group_id","default":null,"nullable":"YES","position":3,"table":"check_in_logs","type":"uuid"},{"column":"action","default":null,"nullable":"NO","position":4,"table":"check_in_logs","type":"text"},{"column":"amount","default":"1","nullable":"NO","position":5,"table":"check_in_logs","type":"int4"},{"column":"door_location","default":null,"nullable":"YES","position":6,"table":"check_in_logs","type":"text"},{"column":"staff_user_id","default":null,"nullable":"YES","position":7,"table":"check_in_logs","type":"uuid"},{"column":"staff_name","default":null,"nullable":"YES","position":8,"table":"check_in_logs","type":"text"},{"column":"created_at","default":"now()","nullable":"NO","position":9,"table":"check_in_logs","type":"timestamptz"},{"column":"venue_id","default":null,"nullable":"YES","position":10,"table":"check_in_logs","type":"uuid"},{"column":"id","default":"gen_random_uuid()","nullable":"NO","position":1,"table":"groups","type":"uuid"},{"column":"service_day_id","default":null,"nullable":"YES","position":2,"table":"groups","type":"uuid"},{"column":"name","default":null,"nullable":"NO","position":3,"table":"groups","type":"text"},{"column":"group_type","default":"'General Guest List'::text","nullable":"NO","position":4,"table":"groups","type":"text"},{"column":"host_name","default":null,"nullable":"YES","position":5,"table":"groups","type":"text"},{"column":"table_location","default":null,"nullable":"YES","position":6,"table":"groups","type":"text"},{"column":"approved_by","default":null,"nullable":"YES","position":7,"table":"groups","type":"text"},{"column":"notes","default":null,"nullable":"YES","position":8,"table":"groups","type":"text"},{"column":"status","default":"'Active'::text","nullable":"NO