","position":17,"table":"guests","type":"bool"},{"column":"late_add_approved_by","default":null,"nullable":"YES","position":18,"table":"guests","type":"text"},{"column":"late_add_reason","default":null,"nullable":"YES","position":19,"table":"guests","type":"text"},{"column":"venue_id","default":null,"nullable":"YES","position":20,"table":"guests","type":"uuid"},{"column":"id","default":"gen_random_uuid()","nullable":"NO","position":1,"table":"service_days","type":"uuid"},{"column":"venue_id","default":null,"nullable":"YES","position":2,"table":"service_days","type":"uuid"},{"column":"service_date","default":null,"nullable":"NO","position":3,"table":"service_days","type":"date"},{"column":"day_name","default":null,"nullable":"NO","position":4,"table":"service_days","type":"text"},{"column":"created_at","default":"now()","nullable":"NO","position":5,"table":"service_days","type":"timestamptz"},{"column":"id","default":"gen_random_uuid()","nullable":"NO","position":1,"table":"shift_notes","type":"uuid"},{"column":"service_day_id","default":null,"nullable":"NO","position":2,"table":"shift_notes","type":"uuid"},{"column":"category","default":"'General Note'::text","nullable":"NO","position":3,"table":"shift_notes","type":"text"},{"column":"priority","default":"'Normal'::text","nullable":"NO","position":4,"table":"shift_notes","type":"text"},{"column":"note_text","default":null,"nullable":"NO","position":5,"table":"shift_notes","type":"text"},{"column":"created_by_user_id","default":null,"nullable":"YES","position":6,"table":"shift_notes","type":"uuid"},{"column":"created_by_name","default":"'Unknown'::text","nullable":"NO","position":7,"table":"shift_notes","type":"text"},{"column":"created_at","default":"now()","nullable":"NO","position":8,"table":"shift_notes","type":"timestamptz"},{"column":"venue_id","default":null,"nullable":"YES","position":9,"table":"shift_notes","type":"uuid"},{"column":"id","default":null,"nullable":"NO","position":1,"table":"staff_profiles","type":"uuid"},{"column":"full_name","default":null,"nullable":"NO","position":2,"table":"staff_profiles","type":"text"},{"column":"role","default":"'door'::text","nullable":"NO","position":3,"table":"staff_profiles","type":"text"},{"column":"active","default":"true","nullable":"NO","position":4,"table":"staff_profiles","type":"bool"},{"column":"created_at","default":"now()","nullable":"NO","position":5,"table":"staff_profiles","type":"timestamptz"},{"column":"venue_id","default":null,"nullable":"YES","position":6,"table":"staff_profiles","type":"uuid"},{"column":"id","default":"gen_random_uuid()","nullable":"NO","position":1,"table":"venues","type":"uuid"},{"column":"name","default":null,"nullable":"NO","position":2,"table":"venues","type":"text"},{"column":"created_at","default":"now()","nullable":"NO","position":3,"table":"venues","type":"timestamptz"}]$expected$::jsonb THEN
