fkey","table":"shift_notes","type":"f"},{"definition":"PRIMARY KEY (id)","name":"shift_notes_pkey","table":"shift_notes","type":"p"},{"definition":"FOREIGN KEY (service_day_id) REFERENCES service_days(id) ON DELETE CASCADE","name":"shift_notes_service_day_id_fkey","table":"shift_notes","type":"f"},{"definition":"FOREIGN KEY (venue_id) REFERENCES venues(id) ON DELETE SET NULL","name":"shift_notes_venue_id_fkey","table":"shift_notes","type":"f"},{"definition":"FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE","name":"staff_profiles_id_fkey","table":"staff_profiles","type":"f"},{"definition":"PRIMARY KEY (id)","name":"staff_profiles_pkey","table":"staff_profiles","type":"p"},{"definition":"CHECK (role = ANY (ARRAY['admin'::text, 'manager'::text, 'door'::text, 'viewer'::text]))","name":"staff_profiles_role_check","table":"staff_profiles","type":"c"},{"definition":"FOREIGN KEY (venue_id) REFERENCES venues(id) ON DELETE SET NULL","name":"staff_profiles_venue_id_fkey","table":"staff_profiles","type":"f"},{"definition":"PRIMARY KEY (id)","name":"venues_pkey","table":"venues","type":"p"}]$expected$::jsonb THEN
