:"CREATE INDEX shift_notes_venue_id_idx ON public.shift_notes USING btree (venue_id)","name":"shift_notes_venue_id_idx","table":"shift_notes"},{"definition":"CREATE UNIQUE INDEX staff_profiles_pkey ON public.staff_profiles USING btree (id)","name":"staff_profiles_pkey","table":"staff_profiles"},{"definition":"CREATE INDEX staff_profiles_venue_id_idx ON public.staff_profiles USING btree (venue_id)","name":"staff_profiles_venue_id_idx","table":"staff_profiles"},{"definition":"CREATE UNIQUE INDEX venues_pkey ON public.venues USING btree (id)","name":"venues_pkey","table":"venues"}]$expected$::jsonb THEN
